body.t-cyberpunk .bg-fx {
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(0,0,0,.16) 3px 4px);
  opacity: .8;
}
body.t-cyberpunk .hero h1 {
  text-shadow: 3px 0 var(--accent-2), -3px 0 var(--accent);
  animation: glitch 3.2s infinite;
}
@keyframes glitch {
  0%, 91%, 94%, 100% { text-shadow: 3px 0 var(--accent-2), -3px 0 var(--accent); transform: none; }
  92% { text-shadow: -4px 0 var(--accent-2), 4px 0 var(--accent); transform: translateX(2px); }
  93% { text-shadow: 4px 0 var(--accent-2), -4px 0 var(--accent); transform: translateX(-2px); }
}
body.t-cyberpunk .section-title { text-shadow: 0 0 22px color-mix(in srgb, var(--accent) 55%, transparent); }
body.t-cyberpunk .card { clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px)); }
body.t-cyberpunk .card:hover { box-shadow: 0 0 28px rgba(255,46,136,.25), inset 0 0 22px rgba(0,229,255,.06); }
body.t-cyberpunk .card.featured::before { border-radius: 0; padding: 3px 12px; }
body.t-cyberpunk .btn { clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px)); border-radius: 0; }
